#include <iostream>
#include <vector>
#include <cassert>

int main() {
  std::vector<int> vec = {1, 2, 3};
  // Direct access using operator[]
  std::cout << vec[1] << std::endl; // Accesses element at index 1 (value 2)
  vec[1] = 10; // Modifies element at index 1
  std::cout << vec[1] << std::endl; // Prints 10
  // Accessing out of bounds is undefined behavior.
  // assert(vec[3] == 0); // This will likely crash or produce unpredictable results
  try {
    std::cout << vec.at(3) << std::endl; // Using at() for safe access with bounds checking
  } catch (const std::out_of_range& oor) {
    std::cerr << "Out of Range error: " << oor.what() << '\n';
  }
  return 0;
}
